def solve(g):
    h,w=len(g),len(g[0])
    b=Counter(c for r in g for c in r).most_common(1)[0][0]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=b]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    o=[r[:] for r in g]
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if o[i][j]==b: o[i][j]=2
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if o[i][j]==b: o[i][j]=2
    return o
